import {
	MASK_AFFECT_DYNAMIC,
	MASK_AFFECT_LIGHTMAPPED,
	MASK_BAKE,
	SHADERDEF_AFFECT_DYNAMIC,
	SHADERDEF_AFFECT_LIGHTMAPPED,
	SHADERDEF_BAKE
} from "./constants.js";
const lightMaskToShaderDefs = (mask) => (mask & MASK_AFFECT_DYNAMIC ? SHADERDEF_AFFECT_DYNAMIC : 0) | (mask & MASK_AFFECT_LIGHTMAPPED ? SHADERDEF_AFFECT_LIGHTMAPPED : 0) | (mask & MASK_BAKE ? SHADERDEF_BAKE : 0);
const shaderDefsToLightMask = (shaderDefs) => (shaderDefs & SHADERDEF_AFFECT_DYNAMIC ? MASK_AFFECT_DYNAMIC : 0) | (shaderDefs & SHADERDEF_AFFECT_LIGHTMAPPED ? MASK_AFFECT_LIGHTMAPPED : 0) | (shaderDefs & SHADERDEF_BAKE ? MASK_BAKE : 0);
export {
	lightMaskToShaderDefs,
	shaderDefsToLightMask
};
